SELECT COUNT(*) 
FROM orders 
WHERE course_id IN (SELECT id FROM courses WHERE category = 'backend');

SELECT COUNT(*) AS missing_score_count
FROM quiz_attempts
WHERE score IS NULL;

SELECT COUNT(*) AS orders_without_coupon
FROM orders
WHERE coupon_id IS NULL;

SELECT channel, COUNT(*) AS row_count
FROM enrollments
GROUP BY channel;

SELECT device, COUNT(*) AS row_count
FROM study_sessions
GROUP BY device;

SELECT AVG(watched_seconds) AS average_watched_seconds
FROM progress
WHERE watched_seconds IS NOT NULL;
